#!/usr/bin/env node
// Detailed, source-derived catalogue of the active HARBORLIGHT mini-games.
// This exporter reads models only; it never starts an account or writes a save.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';
import { ISLAND_PUZZLE_CATALOG, STORY_CATALOG, storyRoomKinds } from '../harborlight-v1-story-catalog.js';
import { createIslandPuzzle, getIslandPuzzleView } from '../harborlight-v1-island-puzzles.js';
import { ADVENTURE_CATALOG, ADVENTURE_RULES } from '../harborlight-v1-adventures.js';
import { miniGameRoundRules } from '../harborlight-v1-minigames.js';
import { cappedExpeditionReward } from '../harborlight-v1-expedition-hour.js';
import { createOriginalAttempt } from '../harborlight-v1-original-puzzles.js';

const ROOT = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const OUTPUT = path.join(ROOT, 'docs/minigames/catalog.json');
const BASE_URL = 'https://harborlight-dev.web.app/minigames/';
const prior = fs.existsSync(OUTPUT) ? JSON.parse(fs.readFileSync(OUTPUT,'utf8')) : null;
const sourceRefIndex = process.argv.indexOf('--source-ref');
const sourceCommit = (sourceRefIndex >= 0 ? process.argv[sourceRefIndex + 1] : process.env.HARBORLIGHT_MINIGAMES_SOURCE_SHA) || prior?.sourceCommit || execFileSync('git',['rev-parse','HEAD'],{cwd:ROOT,encoding:'utf8'}).trim();
if (!/^[a-f0-9]{40}$/.test(sourceCommit)) throw new Error('Expected full source SHA');
const materialNames = {coins:'monety',wood:'drewno',stone:'kamień',grain:'zboże',food:'mąka',planks:'deski'};
const kebab = s => s.replace(/[A-Z]/g, c => '-' + c.toLowerCase());
const source = (name, needle, description) => {
  const body = fs.readFileSync(path.join(ROOT, name), 'utf8');
  const at = body.indexOf(needle);
  if (at < 0) throw new Error(`Missing source anchor: ${name}: ${needle}`);
  return { path: name, line: body.slice(0, at).split('\n').length, description };
};
const commonPractice = [
  'Samodzielny link uruchamia izolowaną próbę testową w bieżącej karcie przeglądarki. Nie wymaga przypisania do prywatnej wyspy ani nie dopisuje nagród do konta gracza.',
  'Poziom, wariant i ponowne rozpoczęcie służą sprawdzeniu planszy. Reguły wyniku są obliczane przez te same moduły co w HARBORLIGHT.',
  'Zamknięcie lub odświeżenie samodzielnej strony rozpoczyna próbę od nowa. Opis zapisu postępu poniżej dotyczy integracji z główną grą, a nie tej niezależnej karty.'
];
const journeyTiming = (duration,kind) => {
  const extension='Gdy pozostaje 30 s, główna gra może wyświetlić pięciosekundowy wybór dodatkowego czasu. Akceptacja za monety kosztuje 10 × najwyższy poziom Ratusza; przedłużenie dodaje co najmniej 60 s lub połowę pozostałego czasu. Reklama wymaga uprawnionego potwierdzenia lub jawnej symulacji testowej.';
  if(['signal-line','harbor-routes'].includes(kind)){
    const base=kind==='signal-line'?180:150;
    return [`Dokładny limit reguł v32: max(90 s, ${base} s − min(60 s, floor(log2(d)) × 5 s)), gdzie d oznacza efektywną trudność. Pierwsza trudność ma ${base} s.`,
      'W łatwiejszej próbie d = max(1, ceil(trudność / 2)); w zwykłej d równa się trudności. floor oznacza zaokrąglenie w dół, ceil w górę. Zegar tego silnika nie korzysta ze wzoru dzielenia przez 1 + 0,06 × (d − 1).',extension];
  }
  if(kind==='memoryTriples')return ['Dokładny limit reguł v32: min(900 s, 240 s + 30 s × (d − 1)), gdzie d to efektywna trudność. Pierwsza trudność ma 240 s; druga 270 s. To rzeczywisty zegar planszy, niezależny od orientacyjnych 420 s w katalogu fabularnym.',
    'Liczba kart wynosi min(120, 24 + 6 × (d − 1)). Od trudności 4 tasowanie następuje co max(30 s, 60 s − 2 s × (d − 4)). W łatwiejszej próbie efektywna trudność jest połową trudności zaokrągloną w górę, co najmniej 1.',extension];
  if(kind==='marbleMaze')return ['Dokładny limit reguł v32: max(60 s, 180 s / (1 + 0,1 × (d − 1))), gdzie d to efektywna trudność. Pierwsza trudność ma 180 s; druga około 163,64 s. To rzeczywisty zegar planszy, niezależny od orientacyjnych 420 s w katalogu fabularnym.',
    'Liczba kulek wynosi min(6, 1 + floor((d − 1) / 2)), a bok labiryntu min(8, 3 + floor((d − 1) / 3)) pól. W łatwiejszej próbie efektywna trudność jest połową trudności zaokrągloną w górę, co najmniej 1.',extension];
  return [`Referencyjny czas katalogowy tej zagadki: ${duration} s. Na pierwszej trudności rzeczywisty limit wynosi ${duration} s.`,
    'Dla tej zagadki limit wynosi max(60 s, czas katalogowy / (1 + 0,06 × (trudność − 1))). W łatwiejszej próbie zamiast zwykłej trudności stosowana jest połowa trudności zaokrąglona w górę, co najmniej 1.',extension];
};
